class Solution {
public:
    int minJumps(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return 0;
        const int M = 1000000;
        vector<int> spf(M + 1, 0);
        vector<int> primes;
        for (int i = 2; i <= M; i++) {
            if (spf[i] == 0) { spf[i] = i; primes.push_back(i); }
            for (int p : primes) {
                if (p > spf[i] || (long long)p * i > M) break;
                spf[p * i] = p;
            }
        }
        unordered_map<int, vector<int>> bucket;
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            while (x > 1) {
                int p = spf[x];
                bucket[p].push_back(i);
                while (x % p == 0) x /= p;
            }
        }
        vector<int> dist(n, -1);
        vector<int> q;
        q.reserve(n);
        q.push_back(0);
        dist[0] = 0;
        for (size_t head = 0; head < q.size(); head++) {
            int i = q[head];
            if (i == n - 1) return dist[i];
            int d = dist[i];
            if (i + 1 < n && dist[i + 1] < 0) { dist[i + 1] = d + 1; q.push_back(i + 1); }
            if (i - 1 >= 0 && dist[i - 1] < 0) { dist[i - 1] = d + 1; q.push_back(i - 1); }
            int x = nums[i];
            if (x >= 2 && spf[x] == x) {
                auto it = bucket.find(x);
                if (it != bucket.end()) {
                    for (int j : it->second)
                        if (dist[j] < 0) { dist[j] = d + 1; q.push_back(j); }
                    bucket.erase(it);
                }
            }
        }
        return -1;
    }
};
